      "path": "dsh-proxy/src/tokenretry.ts",
      "content": "/**\n * Launch-token auto-login for the LAN proxy (DSH 0.2.x).\n *\n * WHY THIS EXISTS: the harness gates its whole web surface behind a per-process\n * launch token. A navigation without the token gets `401 dsh web authentication\n * required; reopen the URL printed by dsh web.`, and only `GET /?token=...`\n * converts that token into a signed 30-day cookie. A LAN device therefore needs\n * somebody to read the token off the `dsh web` startup log and paste it into\n * the URL — one manual step per device, repeated after every restart.\n *\n * This module removes that step. The proxy performs the very exchange a browser\n * performs by hand, on the client's behalf, before the client's own request is\n * forwarded:\n *\n *   1. probe the upstream with the client's exact path and headers;\n *   2. if it answers 401, append `?token=...` and forward the client's request\n *      instead — DSH then mints the cookie and 303-redirects to `./`, so the\n *      browser lands on the app and keeps the cookie for every later request;\n *   3. any other status means the request was fine, so it is forwarded as-is.\n *\n * Only the index request qualifies. DSH accepts the launch token at exactly\n * `GET /` (its `authorizeIndex` requires `pathname === \"/\"` and a single\n * `token`), so on any other path the token could not mint a cookie even if we\n * sent it — and it would leak the token into URLs, logs, and upstream access\n * records for nothing. Every other request therefore flows through untouched,\n * exactly as it would with the feature off.\n *\n * The decision is made by ASKING THE UPSTREAM, never by guessing from the\n * headers a client happens to carry. An earlier version skipped the probe when\n * the request had any `dsh-auth-*` cookie, treating \"carries a session cookie\"\n * as \"carries a valid session\". That is false: DSH's cookie is named\n * `dsh-auth-<base64url(sha256(authority))>` — a name that changes with the\n * upstream port — and its value expires after `cookieMaxAgeDays` or stops\n * verifying when the signing record changes. A browser holding any such cookie\n * (a stale one from an earlier upstream port, an expired one, one signed by a\n * different Harness home) was then declared authenticated, never re-exchanged,\n * and every reload answered `dsh web authentication required` — a permanent\n * lockout that the feature could not recover from, because the cookie it was\n * keyed on is exactly what kept the exchange from happening.\n *\n * WHY A PROBE INSTEAD OF RETRYING IN `proxyRes`: http-proxy 1.18 emits\n * `proxyRes` BEFORE it copies the upstream status/headers onto `res` and pipes\n * the body. A retry issued from that handler would still ship the 401 to the\n * browser and then write a second response over a finished socket. Probing puts\n * the whole decision on the proxy's side of the wire, where nothing has been\n * sent to the client yet. The probe is one body-less GET per index request, so\n * the guess-free rule costs almost nothing.\n *\n * The token is read from the host Connection service (`ctx.connection\n * .authenticatedUrl()`) — the same value `dsh web` prints at startup. Nothing\n * is minted, guessed or persisted here; when the host cannot supply a token the\n * feature stays inert and the proxy behaves exactly as before.\n *\n * SECURITY: with this enabled, any device that can reach the proxy port is\n * admitted by DSH without knowing the launch token, so the proxy's own Basic\n * Auth gate becomes the only barrier. That is why it defaults to OFF and why\n * the settings page tells the user to pair it with a username and password.\n */\nimport http from 'node:http'\n\n/** Upstream coordinates, resolved once from the proxy's own options. */\ninterface AutoLoginTarget {\n  host: string\n  port: number\n}\n\nexport interface LaunchTokenAutoLoginOptions {\n  /** Upstream DSH bind host. */\n  upstreamHost: string\n  /** Upstream DSH port. */\n  upstreamPort: number\n  /** The host's launch token; undefined/empty disables the feature. */\n  launchToken?: string\n  /** Log sink. */\n  log?: (level: 'info' | 'warn' | 'error', message: string) => void\n}\n\n/**\n * Decide whether a client's request may be upgraded with the launch token.\n *\n * Only a GET of the index qualifies: that is the single request DSH accepts a\n * token on, and the only one whose answer can mint the session cookie. See the\n * header comment — replaying a token onto any other path is both useless (DSH\n * rejects it) and wrong in principle, and would leak the token into URLs.\n */\nfunction isTokenExchangeCandidate(method: string | undefined, pathname: string): boolean {\n  const isGet = method === undefined || method === 'GET'\n  return isGet && pathname === '/'\n}\n\n/** True when the URL already carries a token, so appending one would double it. */\nfunction carriesToken(url: URL): boolean {\n  // DSH rejects a request whose `token` appears more than once, so a URL that\n  // already carries one must be forwarded exactly as the client sent it.\n  return url.searchParams.has('token')\n}\n\n/** Append `?token=...` to a request URL, preserving any existing query. */\nfunction withToken(url: string, token: string): string {\n  const parsed = new URL(url, 'http://dsh-proxy.local')\n  parsed.searchParams.set('token', token)\n  // Only path+query belongs on the wire; the base was a parsing anchor.\n  return `${parsed.pathname}${parsed.search}`\n}\n\n/**\n * Send one GET upstream and report only its status code.\n *\n * The response body is drained and discarded — it is never the client's data,\n * it only tells the proxy whether the request would have been accepted.\n * Rejects on transport failure so the caller can fall through to a plain\n * forward (which then reports the real error through the proxy's own handler).\n */\nfunction probeStatus(\n  target: AutoLoginTarget,\n  path: string,\n  headers: http.IncomingHttpHeaders,\n): Promise<number> {\n  return new Promise((resolve, reject) => {\n    const req = http.request(\n      {\n        host: target.host,\n        port: target.port,\n        path,\n        method: 'GET',\n        // The probe impersonates the client, so it must present the same Host\n        // the forwarded request will — otherwise DSH would evaluate a\n        // different authority than the one the real request uses.\n        headers,\n      },\n      (res) => {\n        res.resume()\n        resolve(res.statusCode ?? 0)\n      },\n    )\n    req.on('error', reject)\n    req.end()\n  })\n}\n\n/**\n * Per-proxy launch-token auto-login.\n *\n * One instance owns the upstream coordinates and the token for a single proxy;\n * `enabled` is read once per request to keep the hot path allocation-free.\n */\nexport class LaunchTokenAutoLogin {\n  private readonly target: AutoLoginTarget\n  private readonly token: string\n  private readonly log: LaunchTokenAutoLoginOptions['log']\n\n  constructor(options: LaunchTokenAutoLoginOptions) {\n    this.target = { host: options.upstreamHost, port: options.upstreamPort }\n    this.token = options.launchToken ?? ''\n    this.log = options.log\n  }\n\n  /** True when a token was supplied and the feature can act. */\n  get enabled(): boolean {\n    return this.token !== ''\n  }\n\n  /**\n   * Authenticate one client request with the launch token if it needs it.\n   *\n   * Mutates `req.url` in place when the token should ride along, then lets the\n   * caller forward as usual. Only the index GET is considered, and the decision\n   * comes from the upstream's answer — never from the headers the client\n   * carries. Every other case (feature off, non-index request, token already\n   * present, upstream unreachable, upstream accepted the request) falls through\n   * to a plain forward, so the request is handled exactly as it would be\n   * without this feature.\n   */\n  async grant(req: http.IncomingMessage): Promise<void> {\n    if (!this.enabled) return\n    const url = new URL(req.url ?? '/', 'http://dsh-proxy.local')\n    if (!isTokenExchangeCandidate(req.method, url.pathname)) return\n    if (carriesToken(url)) return\n\n    // Clone the client's headers so the probe presents the same credentials and\n    // negotiation the real request would — but strip the framing headers a\n    // body-less GET must not carry, and never answer from a shared cache: the\n    // whole point is to observe what THIS client would get right now.\n    const browserHeaders: http.IncomingHttpHeaders = { ...req.headers }\n    delete browserHeaders['content-length']\n    delete browserHeaders['transfer-encoding']\n    // The probe is a direct upstream request, so the client's Host (which\n    // points at the proxy) must be replaced by the upstream authority — the\n    // same one changeOrigin makes for the forwarded request.\n    browserHeaders.host = `${this.target.host}:${this.target.port}`\n    browserHeaders['cache-control'] = 'no-cache'\n    browserHeaders.pragma = 'no-cache'\n    let status: number\n    try {\n      status = await probeStatus(this.target, `${url.pathname}${url.search}`, browserHeaders)\n    } catch {\n      // Upstream unreachable: stay out of the way and forward normally, so the\n      // proxy's own error handler reports the real failure to the client.\n      return\n    }\n    if (status !== 401) return\n\n    this.log?.(\n      'info',\n      'launch-token auto-login: upstream answered 401, completing the token exchange on the client’s behalf',\n    )\n    req.url = withToken(req.url ?? '/', this.token)\n  }\n}\n"
    },
    {
      "path": "dsh-proxy/src/session.ts",
      "content": "/**\n * Authentication primitives for the LAN proxy: HTTP Basic Auth is the entire\n * gate, presented through the browser's NATIVE credential dialog — the same\n * model as the standalone dsh-proxy. There is no custom login page and no\n * session cookie: after a successful Basic login the browser caches the\n * credentials for the origin and silently sends them on every request.\n *\n * Password login is active only when BOTH username and password are\n * configured; with either one empty the LAN surface is open (the settings\n * page warns about this).\n */\nimport { timingSafeEqual } from 'node:crypto'\n\n/** Credential pair enforced by the proxy (an empty pair = password login off). */\nexport interface AuthConfig {\n  username: string\n  password: string\n}\n\n/** Constant-time string comparison (length mismatch short-circuits). */\nexport function safeEqual(a: string, b: string): boolean {\n  const ba = Buffer.from(a)\n  const bb = Buffer.from(b)\n  return ba.length === bb.length && timingSafeEqual(ba, bb)\n}\n\n/** Verify an HTTP Basic Authorization header against the configured pair. */\nexport function checkBasicAuth(\n  authorization: string | undefined,\n  username: string,\n  password: string,\n): boolean {\n  const match = /^Basic\\s+(.+)$/i.exec(authorization ?? '')\n  if (!match) return false\n  let decoded: string\n  try {\n    decoded = Buffer.from(match[1], 'base64').toString('utf8')\n  } catch {\n    return false\n  }\n  const sep = decoded.indexOf(':')\n  if (sep === -1) return false\n  return safeEqual(decoded.slice(0, sep), username) && safeEqual(decoded.slice(sep + 1), password)\n}\n\n/** The proxy's gate: Basic Auth only, active when both credentials are set. */\nexport class Authenticator {\n  constructor(readonly config: AuthConfig) {}\n\n  /** Password login is active only when both username and password are set. */\n  get enabled(): boolean {\n    return this.config.username !== '' && this.config.password !== ''\n  }\n\n  isAuthenticated(authorization: string | undefined): boolean {\n    if (!this.enabled) return true\n    return checkBasicAuth(authorization, this.config.username, this.config.password)\n  }\n}\n"
    },
    {
      "path": "dsh-proxy/src/controller.ts",
      "content": "/**\n * ProxyController: owns the lifecycle of the LAN proxy inside the harness —\n * effective options (cordis config overlaid with the persisted runtime\n * settings), start/stop/restart, and the status/update verbs the settings\n * page calls. No cordis dependency: the plugin entry in index.ts wires it\n * into the harness, which keeps every business rule unit-testable against a\n * real in-process upstream.\n */\nimport { lanAddresses, startLanProxy, type LanProxyHandle } from './proxy.ts'\nimport { RuntimeSettingsFile, normalizeRuntimeSettings, validateUpdate } from './settings.ts'\nimport type { LanProxyStatus, LanProxyUpdatePayload, LanProxyUpdateResult } from './contract.ts'\n\n/** The fully-resolved runtime options of one proxy instance. */\nexport interface EffectiveProxyOptions {\n  listenHost: string\n  listenPort: number\n  upstreamHost: string\n  upstreamPort: number\n  username: string\n  password: string\n  launchToken?: string\n  /** Whether launch-token auto-login is enabled. */\n  skipLaunchToken?: boolean\n}\n\nexport interface ProxyControllerOptions {\n  /** Options from the cordis config (schema defaults applied, upstream port resolved). */\n  base: EffectiveProxyOptions\n  /** Path of the persisted runtime-settings JSON. */\n  settingsFile: string\n  /** Log sink (the plugin passes ctx.logger-based printer). */\n  log: (level: 'info' | 'warn' | 'error', message: string) => void\n  /**\n   * Re-reads the host's current launch token. Called when the proxy starts\n   * with auto-login on, and again whenever the settings page turns the flag on\n   * — the token is per-process, so it is never persisted, only the flag is.\n   */\n  readLaunchToken?: () => string | undefined\n}\n\nexport type UpdateOutcome =\n  | { ok: true; result: LanProxyUpdateResult }\n  | { ok: false; message: string }\n\n/** Result of one start attempt: a failed bind reports the reason instead of passing silently. */\nexport type StartOutcome =\n  | { ok: true }\n  | { ok: false; message: string }\n\n/** Upstream reachability probe: connection timeout. */\nconst PROBE_TIMEOUT_MS = 1500\n/** Upstream reachability probe: result cache lifetime. */\nconst PROBE_CACHE_MS = 3000\n\nexport class ProxyController {\n  private handle: LanProxyHandle | null = null\n  private boundPort: number | null = null\n  private probeCache: { at: number; reachable: boolean } | null = null\n  private readonly settings: RuntimeSettingsFile\n  private readonly log: ProxyControllerOptions['log']\n  private options: EffectiveProxyOptions\n\n  constructor(private readonly opts: ProxyControllerOptions) {\n    this.log = opts.log\n    this.settings = new RuntimeSettingsFile(opts.settingsFile)\n    this.options = { ...opts.base }\n    const persisted = this.settings.read()\n    if (persisted.listenPort !== undefined) this.options.listenPort = persisted.listenPort\n    if (persisted.upstreamPort !== undefined) this.options.upstreamPort = persisted.upstreamPort\n    if (persisted.username !== undefined) this.options.username = persisted.username\n    if (persisted.password !== undefined) this.options.password = persisted.password\n    // The launch token itself is never persisted (it is per-process and the\n    // host re-reads it on every start); only the flag is. Turning the flag on\n    // while no token was supplied keeps auto-login off until the token can be\n    // read, which `start()` and `update()` both do.\n    if (persisted.skipLaunchToken !== undefined) this.options.skipLaunchToken = persisted.skipLaunchToken\n  }\n\n  /** Whether a persisted runtime override exists (drives the status flag). */\n  private persisted(): boolean {\n    const current = this.settings.read()\n    return current.listenPort !== undefined\n      || current.upstreamPort !== undefined\n      || current.username !== undefined\n      || current.password !== undefined\n      || current.skipLaunchToken !== undefined\n  }\n\n  /**\n   * Start the proxy (idempotent). Listen errors — the port is already taken,\n   * e.g. by the standalone dsh-proxy — are logged loudly and reported through\n   * the outcome (never thrown), so a failed forwarder can never take down the\n   * web app boot while callers still learn why the listener is down.\n   */\n  async start(): Promise<StartOutcome> {\n    if (this.handle !== null) return { ok: true }\n    const log = this.log\n    // Resolve the launch token HERE, not at construction: the read is deferred\n    // until the harness is serving, and `start()` is the first point where the\n    // webServer (and therefore BrowserAuth behind `connection`) is fully up.\n    if (this.options.skipLaunchToken === true && this.opts.readLaunchToken !== undefined) {\n      const token = this.opts.readLaunchToken()\n      if (token === undefined || token === '') {\n        log('warn', 'dsh-proxy: skipLaunchToken is on but the host supplied no launch token; the LAN surface still requires DSH authentication')\n      } else {\n        this.options.launchToken = token\n        log('info', 'dsh-proxy: launch-token auto-login enabled — a first-time browser is authenticated without the token')\n      }\n    }\n    const handle = startLanProxy({\n      listenHost: this.options.listenHost,\n      listenPort: this.options.listenPort,\n      upstreamHost: this.options.upstreamHost,\n      upstreamPort: this.options.upstreamPort,\n      username: this.options.username,\n      password: this.options.password,\n      launchToken: this.options.launchToken,\n      log,\n    })\n    this.handle = handle\n    try {\n      const bound = await handle.ready\n      this.boundPort = bound\n      const urls = handle.describeUrls(bound)\n      log('info', `dsh-proxy: listening on ${this.options.listenHost}:${bound} -> http://${this.options.upstreamHost}:${this.options.upstreamPort}`)\n      log('info', `dsh-proxy: 本机访问 ${urls.local}`)\n      for (const url of urls.lan) log('info', `dsh-proxy: 局域网访问 ${url}`)\n      if (this.options.username !== '' && this.options.password !== '') {\n        log('info', `dsh-proxy: password login enabled (username: ${this.options.username}) — browser Basic Auth`)\n      } else if (this.options.username !== '' || this.options.password !== '') {\n        log('warn', 'dsh-proxy: password login NOT enabled — username and password must BOTH be set (only one is configured); the LAN surface is open')\n      } else {\n        log('warn', 'dsh-proxy: password login is disabled (username and password are both empty); the LAN surface is open')\n      }\n      if (this.options.launchToken !== undefined && this.options.launchToken !== '') {\n        log('info', 'dsh-proxy: launch-token auto-login ON — a first-time browser is authenticated without the token')\n      }\n      return { ok: true }\n    } catch (err) {\n      const message = err instanceof Error ? err.message : String(err)\n      log('error', `dsh-proxy: failed to listen on ${this.options.listenHost}:${this.options.listenPort}: ${message} — stop any other dsh-proxy on this port, or change listenPort`)\n      this.handle = null\n      return {\n        ok: false,\n        message: `无法监听 ${this.options.listenHost}:${this.options.listenPort}：${message}。该端口可能已被占用，请更换代理服务端口或释放该端口后重试。`,\n      }\n    }\n  }\n\n  /** Stop the proxy and every upgraded socket. */\n  async stop(): Promise<void> {\n    const handle = this.handle\n    this.handle = null\n    this.boundPort = null\n    if (handle !== null) await handle.close()\n  }\n\n  /** Stop and start again with the current effective options (the \"restart the forwarding service\" verb). */\n  async restart(): Promise<StartOutcome> {\n    await this.stop()\n    return this.start()\n  }\n\n  /**\n   * Stop the proxy AFTER the caller's response has flushed back. The stop RPC\n   * answer travels through the proxy itself when the settings page is reached\n   * via the LAN URL, so closing the listener before the response is written\n   * would drop it; the listener is torn down shortly afterwards instead.\n   * @param delayMs - grace before the listener closes (defaults to 300ms).\n   * @returns the status as it will be once stopped.\n   */\n  stopDeferred(delayMs = 300): LanProxyStatus {\n    const stopped: LanProxyStatus = { ...this.status(), proxyListening: false }\n    const timer = setTimeout(() => {\n      void this.stop()\n    }, delayMs)\n    timer.unref?.()\n    return stopped\n  }\n\n  /**\n   * Current read-only status for the settings page. `upstreamReachable`\n   * reflects the most recent probe (false until the first probe runs).\n   */\n  status(): LanProxyStatus {\n    return {\n      listenHost: this.options.listenHost,\n      listenPort: this.boundPort ?? this.options.listenPort,\n      proxyListening: this.boundPort !== null,\n      upstreamHost: this.options.upstreamHost,\n      upstreamPort: this.options.upstreamPort,\n      upstreamReachable: this.probeCache?.reachable ?? false,\n      username: this.options.username,\n      password: this.options.password,\n      authEnabled: this.options.username !== '' && this.options.password !== '',\n      skipLaunchToken: this.options.skipLaunchToken === true,\n      persisted: this.persisted(),\n    }\n  }\n\n  /**\n   * Status with a fresh upstream reachability probe (cached for a few\n   * seconds so repeated settings-page loads do not hammer the target).\n   */\n  async refreshStatus(): Promise<LanProxyStatus> {\n    await this.probeUpstream()\n    return this.status()\n  }\n\n  /**\n   * Probe whether the target upstream service answers HTTP. Any response —\n   * even an error status — counts as reachable; only connection failures and\n   * timeouts turn the light red.\n   */\n  private async probeUpstream(): Promise<boolean> {\n    const now = Date.now()\n    if (this.probeCache !== null && now - this.probeCache.at < PROBE_CACHE_MS) {\n      return this.probeCache.reachable\n    }\n    const controller = new AbortController()\n    const timer = setTimeout(() => controller.abort(), PROBE_TIMEOUT_MS)\n    let reachable = false\n    try {\n      const res = await fetch(\n        `http://${this.options.upstreamHost}:${this.options.upstreamPort}/favicon.svg`,\n        { signal: controller.signal, redirect: 'manual' },\n      )\n      reachable = true\n      await res.body?.cancel().catch(() => {})\n    } catch {\n      reachable = false\n    } finally {\n      clearTimeout(timer)\n    }\n    this.probeCache = { at: now, reachable }\n    return reachable\n  }\n\n  /**\n   * Apply an update payload: validate, persist, then restart the forwarding\n   * service with the new effective options.\n   * @param payload - raw RPC payload from the settings page.\n   * @returns the new status, or a user-facing rejection message.\n   */\n  async update(payload: unknown): Promise<UpdateOutcome> {\n    // Validate against the actually bound port: with listenPort 0 the OS\n    // assigns the port, and the configured 0 must never be the comparison.\n    const check = validateUpdate(\n      payload,\n      this.boundPort ?? this.options.listenPort,\n      this.options.upstreamPort,\n    )\n    if (!check.ok) return { ok: false, message: check.message }\n    const patch = check.patch as LanProxyUpdatePayload\n\n    const next: LanProxyUpdatePayload = { ...this.settings.read(), ...patch }\n    this.settings.write(next)\n\n    if (patch.listenPort !== undefined) this.options.listenPort = patch.listenPort\n    if (patch.upstreamPort !== undefined) this.options.upstreamPort = patch.upstreamPort\n    if (patch.username !== undefined) this.options.username = patch.username\n    if (patch.password !== undefined) this.options.password = patch.password\n    if (patch.skipLaunchToken !== undefined) this.options.skipLaunchToken = patch.skipLaunchToken\n    // Auto-login needs the actual token, which is read from the host (lazily,\n    // because BrowserAuth only exists once the harness is serving). Re-read it\n    // whenever the flag is being turned on so the settings page takes effect\n    // without a dsh web restart; turning it OFF clears the cached token.\n    if (patch.skipLaunchToken === true && this.opts.readLaunchToken !== undefined) {\n      this.options.launchToken = this.opts.readLaunchToken() ?? this.options.launchToken\n      if (this.options.launchToken === undefined || this.options.launchToken === '') {\n        this.log('warn', 'dsh-proxy: the host supplied no launch token, so auto-login cannot take effect until dsh web restarts')\n      }\n    }\n    if (patch.skipLaunchToken === false) this.options.launchToken = undefined\n\n    // A running service must restart to pick up the new effective options; a\n    // stopped service is just saved and stays stopped (starting it is the\n    // explicit start control's job).\n    const wasListening = this.boundPort !== null\n    const startOutcome = wasListening ? await this.restart() : null\n    this.probeCache = null\n    this.log('info', `dsh-proxy: settings updated via the settings page; forwarding service ${startOutcome === null ? 'kept stopped' : startOutcome.ok ? 'restarted' : 'restart FAILED'}`)\n    const bothSet = this.options.username !== '' && this.options.password !== ''\n    const anySet = this.options.username !== '' || this.options.password !== ''\n    const partial = anySet && !bothSet\n\n    if (startOutcome !== null && !startOutcome.ok) {\n      return {\n        ok: true,\n        result: {\n          status: await this.refreshStatus(),\n          notice: 'saved-restart-failed',\n          message: startOutcome.message,\n        },\n      }\n    }\n    const notice: 'saved' | 'saved-restarted' | 'credentials-partial-saved' | 'credentials-partial-restarted'\n      = startOutcome === null\n        ? (partial ? 'credentials-partial-saved' : 'saved')\n        : (partial ? 'credentials-partial-restarted' : 'saved-restarted')\n    return {\n      ok: true,\n      result: {\n        status: await this.refreshStatus(),\n        notice,\n        message: startOutcome === null\n          ? (partial ? '已保存（注意：需同时设置用户名和密码才会启用密码登录）' : '已保存')\n          : (partial ? '已保存并重启转发服务（注意：需同时设置用户名和密码才会启用密码登录）' : '已保存并重启转发服务'),\n      },\n    }\n  }\n}\n"
    },
    {
      "path": "dsh-proxy/src/settings.ts",
      "content": "/**\n * Persisted runtime settings for the LAN proxy: a small JSON file under the\n * DSH home that overlays the cordis config. The settings page writes here so\n * changes survive `dsh web` restarts; the file is the single source of truth\n * for the runtime overrides (proxy listen port, username, password).\n */\nimport { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs'\nimport { dirname } from 'node:path'\nimport type { LanProxyUpdatePayload } from './contract.ts'\n\n/** The on-disk shape (a subset of the update payload; no derived fields). */\nexport interface PersistedRuntimeSettings {\n  /** Proxy listen port override. */\n  listenPort?: number\n  /** Deprecated forward-target override, kept for legacy persisted files. */\n  upstreamPort?: number\n  username?: string\n  password?: string\n  /** Launch-token auto-login override; see LanProxyUpdatePayload. */\n  skipLaunchToken?: boolean\n}\n\n/** Tolerant read of an unknown JSON value into the persisted shape. */\nexport function normalizeRuntimeSettings(raw: unknown): PersistedRuntimeSettings {\n  if (typeof raw !== 'object' || raw === null) return {}\n  const source = raw as Record<string, unknown>\n  const out: PersistedRuntimeSettings = {}\n  if (typeof source.listenPort === 'number' && Number.isInteger(source.listenPort)) {\n    out.listenPort = source.listenPort\n  }\n  if (typeof source.upstreamPort === 'number' && Number.isInteger(source.upstreamPort)) {\n    out.upstreamPort = source.upstreamPort\n  }\n  if (typeof source.username === 'string') out.username = source.username\n  if (typeof source.password === 'string') out.password = source.password\n  if (typeof source.skipLaunchToken === 'boolean') out.skipLaunchToken = source.skipLaunchToken\n  return out\n}\n\n/**\n * Read/write access to the persisted settings file. Writes are atomic\n * (temp file + rename) so a crash never leaves a truncated JSON behind.\n */\nexport class RuntimeSettingsFile {\n  constructor(private readonly filePath: string) {}\n\n  read(): PersistedRuntimeSettings {\n    let text: string\n    try {\n      text = readFileSync(this.filePath, 'utf8')\n    } catch {\n      return {}\n    }\n    try {\n      return normalizeRuntimeSettings(JSON.parse(text))\n    } catch {\n      return {}\n    }\n  }\n\n  write(settings: PersistedRuntimeSettings): void {\n    mkdirSync(dirname(this.filePath), { recursive: true })\n    const temp = `${this.filePath}.tmp`\n    writeFileSync(temp, JSON.stringify(settings, null, 2) + '\\n', 'utf8')\n    renameSync(temp, this.filePath)\n  }\n}\n\nexport type UpdateValidation =\n  | { ok: true; patch: Required<Pick<LanProxyUpdatePayload, 'listenPort' | 'upstreamPort' | 'username' | 'password' | 'skipLaunchToken'>> & LanProxyUpdatePayload }\n  | { ok: false; message: string }\n\nconst MAX_USERNAME_LENGTH = 64\nconst MAX_PASSWORD_LENGTH = 128\n\n/**\n * Validate an update payload from the settings page.\n * @param payload - the raw RPC payload.\n * @param currentListenPort - the proxy's current listen port.\n * @param currentUpstreamPort - the current forward-target (default service) port.\n * @returns the normalized patch, or a user-facing rejection message.\n */\nexport function validateUpdate(\n  payload: unknown,\n  currentListenPort: number,\n  currentUpstreamPort: number,\n): UpdateValidation {\n  if (typeof payload !== 'object' || payload === null) {\n    return { ok: false, message: '请求体必须是对象' }\n  }\n  const input = payload as Record<string, unknown>\n  const patch: LanProxyUpdatePayload = {}\n\n  if (input.listenPort !== undefined) {\n    const port = input.listenPort\n    if (typeof port !== 'number' || !Number.isInteger(port) || port < 1 || port > 65535) {\n      return { ok: false, message: `代理服务端口无效：${String(port)}（需要 1–65535 的整数）` }\n    }\n    if (port === currentUpstreamPort) {\n      return { ok: false, message: `代理服务端口不能与默认服务端口相同（都是 ${port}）` }\n    }\n    patch.listenPort = port\n  }\n\n  // Deprecated forward-target patch, accepted for legacy persisted configs\n  // and scripts; the settings page no longer edits this port.\n  if (input.upstreamPort !== undefined) {\n    const port = input.upstreamPort\n    if (typeof port !== 'number' || !Number.isInteger(port) || port < 1 || port > 65535) {\n      return { ok: false, message: `转发目标端口无效：${String(port)}（需要 1–65535 的整数）` }\n    }\n    if (port === currentListenPort) {\n      return { ok: false, message: `转发目标端口不能与代理服务端口相同（都是 ${port}）` }\n    }\n    patch.upstreamPort = port\n  }\n\n  if (input.username !== undefined) {\n    if (typeof input.username !== 'string') return { ok: false, message: '用户名必须是字符串' }\n    if (input.username.length > MAX_USERNAME_LENGTH) {\n      return { ok: false, message: `用户名过长（最多 ${MAX_USERNAME_LENGTH} 个字符）` }\n    }\n    patch.username = input.username\n  }\n\n  if (input.password !== undefined) {\n    if (typeof input.password !== 'string') return { ok: false, message: '密码必须是字符串' }\n    if (input.password.length > MAX_PASSWORD_LENGTH) {\n      return { ok: false, message: `密码过长（最多 ${MAX_PASSWORD_LENGTH} 个字符）` }\n    }\n    patch.password = input.password\n  }\n\n  if (input.skipLaunchToken !== undefined) {\n    if (typeof input.skipLaunchToken !== 'boolean') {\n      return { ok: false, message: '免 token 登录开关必须是布尔值' }\n    }\n    patch.skipLaunchToken = input.skipLaunchToken\n  }\n\n  if (\n    patch.listenPort === undefined\n    && patch.upstreamPort === undefined\n    && patch.username === undefined\n    && patch.password === undefined\n    && patch.skipLaunchToken === undefined\n  ) {\n    return { ok: false, message: '没有可保存的修改' }\n  }\n  return {\n    ok: true,\n    patch: patch as Required<Pick<LanProxyUpdatePayload, 'listenPort' | 'upstreamPort' | 'username' | 'password' | 'skipLaunchToken'>> & LanProxyUpdatePayload,\n  }\n}\n"
    }
  ],
